#!/bin/bash
set -euo pipefail

PROJECT_ROOT="$(cd "$(dirname "$0")" && pwd)"
FILE="$PROJECT_ROOT/lib/screens/catalog_screen.dart"

if [ ! -f "$FILE" ]; then
  echo "ОШИБКА: не найден $FILE"
  exit 1
fi

BACKUP="$FILE.backup_$(date +%Y%m%d_%H%M%S)"
cp "$FILE" "$BACKUP"
echo "Создан backup: $BACKUP"

python3 - "$FILE" <<'PY'
import base64
from pathlib import Path
import sys

path = Path(sys.argv[1])
encoded = ''''''
path.write_bytes(base64.b64decode(encoded))
print(f"Перезаписан: {path}")
PY

echo
echo "Готово."
echo "Новая логика Каталога:"
echo "  1. SearchBar остается pinned сверху при вертикальном скролле."
echo "  2. CategoryBar остается pinned непосредственно под SearchBar."
echo "  3. Товары сгруппированы по категориям."
echo "  4. Активный CategoryChip автоматически меняется по текущей секции."
echo "  5. Нажатие категории прокручивает к ее секции."
echo "  6. 'Все' возвращает каталог в начало."
echo "  7. Поиск фильтрует товары, сохраняя группировку по категориям."
echo "  8. Исходный файл сохранен в backup."
echo
echo "Запусти:"
echo "  flutter analyze lib/screens/catalog_screen.dart"
echo "  flutter run"
